	#currency: string | null;
	#exchangeRateToCAD: number | null;
	#matchedTransactionId: string | null;
	#createdAt: string;
	#suspiciousDate: boolean;
	#splitGroupId: string | null;
	#originalFilename: string | null;

	private constructor(row: ReceiptRow) {
		this.#id = row.id;
		this.#userId = row.user_id;
		this.#imagePath = row.receipt_image_path;
		this.#transactionDate = row.transaction_date;
		this.#totalAmount = row.total_amount;
		this.#tax = row.tax;
		this.#merchantName = row.merchant_name;
		this.#creditCardName = row.credit_card_name;
		this.#creditCardLast4 = row.credit_card_last_4;
		this.#currency = row.currency;
		this.#exchangeRateToCAD = row.exchange_rate_to_cad;
		this.#matchedTransactionId = row.matched_transaction_id;
		this.#createdAt = row.created_at;
		this.#suspiciousDate = row.suspicious_date;
		this.#splitGroupId = row.split_group_id ?? null;
		this.#originalFilename = row.original_filename;
	}

	static fromRow(row: ReceiptRow) {
		return new Receipt(row);
	}

	toRow(): ReceiptRow {
		return {
			id: this.#id,
			user_id: this.#userId,
			receipt_image_path: this.#imagePath,
			transaction_date: this.#transactionDate,
			total_amount: this.#totalAmount,
			tax: this.#tax,
			merchant_name: this.#merchantName,
			credit_card_name: this.#creditCardName,
			credit_card_last_4: this.#creditCardLast4,
			currency: this.#currency,
			exchange_rate_to_cad: this.#exchangeRateToCAD,
			matched_transaction_id: this.#matchedTransactionId,
			created_at: this.#createdAt,
			suspicious_date: this.#suspiciousDate,
			split_group_id: this.#splitGroupId,
			original_filename: this.#originalFilename
		};
	}

	get id() {
		return this.#id;
	}
	get userId() {
		return this.#userId;
	}
	get imagePath() {
		return this.#imagePath;
	}
	get transactionDate() {
		return this.#transactionDate;
	}
	get totalAmount() {
		return this.#totalAmount;
	}
	get tax() {
		return this.#tax;
	}
	get merchantName() {
		return this.#merchantName;
	}
	get creditCardName() {
		return this.#creditCardName;
	}
	get creditCardLast4() {
		return this.#creditCardLast4;
	}
	get currency() {
		return this.#currency;
	}
	get exchangeRateToCAD() {
		return this.#exchangeRateToCAD;
	}
	get matchedTransactionId() {
		return this.#matchedTransactionId;
	}
	get createdAt() {
		return this.#createdAt;
	}
	get suspiciousDate() {
		return this.#suspiciousDate;
	}
	get splitGroupId() {
		return this.#splitGroupId;
	}
	get originalFilename() {
		return this.#originalFilename;
	}
}

